  "privTitle": "Personvern og nettleserlagring",
  "privClose": "Lukk personvernerklæring",
  "privWho": "Hvem er ansvarlig?",
  "privWhat": "Hva vi bruker og hvorfor",
  "privStorage": "Nettleserlagring",
  "privOther": "Andre eksisterende funksjoner",
  "privProviders": "Tjenesteleverandører og internasjonale overføringer",
  "privRetention": "Lagringstid og sletting",
  "privRights": "Dine rettigheter",
  "noticeReopen": "Lagringsmelding",
  "noticeLabel": "Melding om nettleserlagring",
  "noticeText": "Cook bruker nettleserlagring for matlagings- og innloggingsfunksjonene du bruker. Ingen lagring for reklame eller analyse legges til.",
  "noticeClose": "Lukk lagringsmelding",
  "privDraftLabel": "Utkast – oppdatert 28. oktober 2026.",
  "privDraft": "Kontofunksjonene testes nå. Opplysningene om operatøren og tjenestene nedenfor må fylles ut før offentlig lansering.",
  "privWho1": "Cook drives av [operatørens juridiske navn og postadresse]. Kontakt [e-postadresse for personvern] med spørsmål og forespørsler om personvern. Disse opplysningene må fylles ut før registreringen åpner.",
  "privWhat1": "Når du oppretter en konto, bruker vi e-postadressen din, en konto-ID, opplysninger om passordautentisering og bekreftelsesstatus for å levere og sikre kontoen din. Passord håndteres av autentiseringsleverandøren som sikre hasher; Cook lagrer ingen lesbare passord. Vi lagrer kjøkkenoppsettet, valgt språk, tema og måleenheter for å gjenopprette innstillingene dine på alle enheter. E-postadresse og passord er nødvendig for å ha en konto; du kan se oppskrifter uten.",
  "privWhat2": "Behandling av konto og innstillinger er nødvendig for å levere kontotjenesten du ber om (personvernforordningen artikkel 6 nr. 1 bokstav b). Begrensede sikkerhets- og misbruksforebyggende opplysninger kan behandles på grunnlag av berettigede interesser (artikkel 6 nr. 1 bokstav f), så langt det er nødvendig og etter en interesseavveining. E-post om bekreftelse og tilbakestilling av passord er tjenestemeldinger, ikke markedsføring. Kontofunksjonen legger ikke til reklame eller analyse.",
  "privStorage1": "Cook bruker sessionStorage til å ta med kjøkkenet, fremdriften i matlagingen og valgene dine mellom sider i samme fane. Når du er logget inn, inneholder den også innloggingsøkten din. Nettleseren sletter vanligvis dette når fanens økt avsluttes, men nettleserens gjenoppretting av økter kan beholde det. Når du logger ut, slettes Cooks fanedata. At du har lukket lagringsmeldingen, lagres bare i den fanen. Cooks egne skript setter ingen informasjonskapsler. Leverandørene av nettstedshotell eller tjenester kan ha egen sikkerhetsbehandling som må dokumenteres før lansering.",
  "privStorage2": "OK og lukkeknappen på lagringsmeldingen lukker bare meldingen. De gir ikke tillatelse til analyse, reklame eller annen valgfri sporing. All framtidig ikke-nødvendig lagring krever et eget valg før den starter, med like enkel avvisning og tilbaketrekking.",
  "privOther1": "Den nåværende talefunksjonen i oppskriftslisten spør country.is om et omtrentlig land basert på IP-adressen din for å velge talespråk. Hvis du bruker mikrofongjenkjenning, kan nettleseren sende lyd til sin leverandør av talegjenkjenning. Du kan også skrive inn ingrediensene. Disse leverandørene, retningslinjene deres og det rettslige grunnlaget for funksjonene må gjennomgås før offentlig lansering.",
  "privProviders1": "Planlagt kontoleverandør: Supabase (administrert PostgreSQL og autentisering) med en valgt databaseregion i EU. E-postleverandør: [leverandør]. Nettstedshotell: [leverandør]. Operatøren må bekrefte de faktiske leverandørene, databehandleravtaler, underleverandører, plassering av logger og eventuelle overføringer utenfor EØS. En databaseregion i EU utelukker ikke i seg selv internasjonale overføringer. Oppgi ved behov gjeldende beslutning om tilstrekkelig beskyttelsesnivå eller avtalemessige garantier og hvordan man får en kopi.",
  "privRetention1": "Kontoinnstillinger lagres så lenge kontoen din er aktiv. Du kan be om sletting via personvernkontakten ovenfor. Før lansering må operatøren fastsette hvordan forespørsler om sletting besvares, når ubekreftede kontoer utløper, og hvor lenge sikkerhetslogger og sikkerhetskopier lagres. Slettede data kan bli liggende i tilgangsbegrensede sikkerhetskopier til den dokumenterte lagringstiden utløper.",
  "privRights1": "Avhengig av gjeldende vilkår kan du be om innsyn, retting, sletting, begrensning eller dataportabilitet, eller protestere mot behandling basert på berettigede interesser. Kontakt operatøren ovenfor; forespørsler besvares normalt innen én måned, og en eventuell lovlig forlengelse forklares. Du kan klage til tilsynsmyndigheten din, blant annet ungarske NAIH på naih.hu. Cook bruker ikke kontoinnstillinger til automatiserte avgjørelser med rettsvirkning eller tilsvarende betydelige følger.",
