  "Even thickness": "Jevn tykkelse",
  "Season the chicken": "Krydre kyllingen",
  "Rub it well in a bowl with salt, a little black pepper and some oil.": "Gni den godt inn i en bolle med salt, litt sort pepper og litt olje.",
  "Evenly coated": "Jevnt dekket",
  "Heat a little oil in the pan on medium-high and add the chicken.": "Varm litt olje i pannen på middels høy varme og legg i kyllingen.",
