  "Make the marinade": "Lag marinaden",
  "Mix the lemon juice, mustard, garlic, crumbled stock cube, pepper, salt and half the oil. Add the chicken and the onions and mix well.": "Bland sitronsaften, sennepen, hvitløken, den smuldrede buljongterningen, pepperen, saltet og halvparten av oljen. Ha i kyllingen og løken og bland godt.",
  "Everything coated": "Alt dekket",
  "Cover and marinate in the fridge for at least 1 hour (or overnight).": "Dekk til og la det marinere i kjøleskapet i minst 1 time (eller over natten).",
  "Lift the chicken out of the marinade (keep the onions and the marinade) and brown it in the rest of the oil. Take it out.": "Løft kyllingen ut av marinaden (ta vare på løken og marinaden) og brun den i resten av oljen. Ta den ut.",
  "Browned on both sides": "Brunet på begge sider",
  "Cook the onions": "Stek løken",
  "Fry the onions from the marinade in the same pan until soft and golden.": "Stek løken fra marinaden i samme panne til den er myk og gyllen.",
  "Add the rest of the marinade, the water and the bay leaf (and the chili), put the chicken back, cover and simmer until the chicken is tender. Add the olives for the last 5 minutes.": "Ha i resten av marinaden, vannet og laurbærbladet (og chilien), legg kyllingen tilbake, legg på lokk og la det småkoke til kyllingen er mør. Ha i olivenene de siste 5 minuttene.",
  "Chicken tender, onions jammy": "Kyllingen mør, løken syltete",
  "Serve the chicken and onions over the rice.": "Server kyllingen og løken på risen.",
  "Brown the chicken … Simmer": "Brun kyllingen … Småkok",
  "whole, pricked": "hel, prikket",
  "Chicken, finely chopped": "Kylling, finhakket",
  "With a crispy fried egg": "Med et sprøtt speilegg",
  "Pound the garlic and chilies": "Støt hvitløk og chili",
  "Pound the garlic and chilies to a rough paste in a mortar (or chop them finely).": "Støt hvitløken og chiliene til en grov pasta i en morter (eller finhakk dem).",
  "Rough paste": "Grov pasta",
  "Mix the oyster sauce, both soy sauces, fish sauce, sugar and water.": "Bland østerssausen, begge soyasausene, fiskesausen, sukkeret og vannet.",
  "Heat the oil in the wok until very hot and fry the eggs one at a time, spooning hot oil over them, until the edges are crispy and the yolk is still runny. Keep them on a plate.": "Varm oljen i woken til den er veldig varm og stek eggene ett om gangen mens du øser varm olje over dem, til kantene er sprø og plommen fortsatt rennende. Sett dem til side på en tallerken.",
